import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

/// Receipt for a simulated USDT withdrawal, including the matching
/// g_messages transaction ID and timestamp generated by PostgreSQL.
class WithdrawalReceipt {
  const WithdrawalReceipt({
    required this.transactionId,
    required this.createdAtUtc,
  });

  final String transactionId;
  final DateTime createdAtUtc;
}

abstract interface class WithdrawalRepository {
  Future<WithdrawalReceipt> withdrawUsdt({
    required double amount,
    required String address,
  });
}

class SupabaseWithdrawalRepository implements WithdrawalRepository {
  const SupabaseWithdrawalRepository(this.client);

  final SupabaseClient client;

  @override
  Future<WithdrawalReceipt> withdrawUsdt({
    required double amount,
    required String address,
  }) async {
    if (!amount.isFinite || amount <= 0) {
      throw ArgumentError.value(amount, 'amount', 'Must be positive');
    }
    if (address.trim().isEmpty) {
      throw ArgumentError.value(address, 'address', 'Cannot be empty');
    }
    if (client.auth.currentUser == null) {
      throw StateError('Sign in before withdrawing.');
    }

    // One atomic PostgreSQL call: deduct the USDT and INSERT the withdrawal
    // message. Neither change commits if the other fails. The message uses
    // auth.uid() for owner_id and the server generates its 100-char ID.
    final response = await client.rpc(
      'b_demo_withdraw_and_message',
      params: {
        'p_amount': amount,
        'p_address': address.trim(),
      },
    );

    if (response is! Map) {
      throw StateError('Withdrawal confirmation was not returned.');
    }

    final transactionId = response['transaction_id']?.toString();
    final createdAt = response['created_at_utc']?.toString();
    if (transactionId == null || transactionId.length != 100 ||
        createdAt == null) {
      throw StateError('Withdrawal confirmation is incomplete.');
    }

    return WithdrawalReceipt(
      transactionId: transactionId,
      createdAtUtc: DateTime.parse(createdAt).toUtc(),
    );
  }
}

final withdrawalRepositoryProvider = Provider<WithdrawalRepository>(
  (ref) => SupabaseWithdrawalRepository(Supabase.instance.client),
);
